def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    stripes=[r for r,row in enumerate(grid) if 8 in row]
    holes={r:[c for c,v in enumerate(grid[r]) if v==0] for r in stripes}
    # A hole sends a vertical ray through the adjacent open band(s); it continues
    # across a stripe only when that stripe has a hole in the same column.
    for c in range(w):
        active=False
        for r in range(h):
            if r in holes:
                if c in holes[r]:
                    active=True
                    if out[r][c]==0: out[r][c]=2
                else:
                    active=False
            elif active and out[r][c]==0:
                out[r][c]=2
        # also propagate a hole upward through the open band above its stripe
        active=False
        for r in range(h-1,-1,-1):
            if r in holes:
                if c in holes[r]:
                    active=True
                    if out[r][c]==0: out[r][c]=2
                else: active=False
            elif active and out[r][c]==0: out[r][c]=2
    # Horizontal rays connect the holes across the blank row above each stripe;
    # a lone hole sends a ray across the entire row.
    for r,cs in holes.items():
        if r==0: continue
        rr=r-1
        lo,hi=(min(cs),max(cs)) if len(cs)>1 else (0,w-1)
        for c in range(lo,hi+1):
            if out[rr][c]==0: out[rr][c]=2
    # The marker's row is unchanged except for the given marker.
    return out
