    # hole then projects into the neighboring open rows.
    mr=next(r for r,row in enumerate(grid) if 2 in row);mc=grid[mr].index(2)
    target=min(gaps[stripes[0]],key=lambda c:abs(c-mc))
    for r in range(mr+1,stripes[0]+1):
        if out[r][target]==0:out[r][target]=2
    # Vertical projections from all gaps run only through open bands, stopping at
    # subsequent striped rows unless they contain a matching gap.
    for c in set(sum(gaps.values(),[])):
        for r in range(stripes[0]+1,h):
            if 8 in grid[r]:
                if grid[r][c]==0:
                    out[r][c]=2
                    continue
