            if out[r][c]==0:out[r][c]=2
    # Join gap endpoints horizontally in blank bands immediately above later stripes.
    for r in stripes[1:]:
        cs=gaps[r]
        for c in range(min(cs),max(cs)+1):
            if out[r-1][c]==0:out[r-1][c]=2
    # Middle full crossbar joins the patterned structure.
    if len(stripes)>=3:
        rr=(stripes[1]+stripes[2])//2
        for c in range(w):
            if out[rr][c]==0:out[rr][c]=2
    return out
