def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    stripes=[r for r,row in enumerate(grid) if 8 in row]
    gaps={r:[c for c,v in enumerate(grid[r]) if v==0] for r in stripes}
    # From the marker, trace through the first gap to its two endpoints and
    # continue those paths along the contours of the broken stripes.
    mr=next(r for r,row in enumerate(grid) if 2 in row); mc=grid[mr].index(2)
    first=gaps[stripes[0]][0]
    for r in range(mr, stripes[0]+1):
        if out[r][first]==0: out[r][first]=2
    # Outer gap boundaries continue vertically down each blank band.
    cols={c for cs in gaps.values() for c in cs}
    for c in cols:
        for r in range(stripes[0]+1,h):
            if 8 in grid[r]:
                if grid[r][c]==0: out[r][c]=2
                else: break
            elif out[r][c]==0: out[r][c]=2
    # Crossbars span from outermost missing positions of each successive stripe.
    for r in stripes[1:]:
        cs=gaps[r]
        rr=r-1
        for c in range(min(cs),max(cs)+1):
            if out[rr][c]==0: out[rr][c]=2
    # One full horizontal bridge joins the two sides midway through the design.
    if len(stripes)>=3:
        rr=(stripes[1]+stripes[2])//2
        for c in range(w):
            if out[rr][c]==0: out[rr][c]=2
    return out
