def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Each unbroken vertical 8-bar is a wall; 2-colored tracks are the adjacent
    # zero columns, extended along the wall's length. Gaps in a wall create
    # horizontal bridges between the neighboring tracks.
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==8:
                # side-adjacent columns mark continuation of the vertical bar
                for cc in (c-1,c+1):
                    if 0<=cc<w and grid[r][cc]==0:
                        # extend this track along the contiguous vertical 8 segment
                        rr=r
                        while rr>0 and grid[rr-1][c]==8: rr-=1
                        top=rr; rr=r
                        while rr+1<h and grid[rr+1][c]==8: rr+=1
                        bot=rr
                        for y in range(top,bot+1):
                            if out[y][cc]==0:out[y][cc]=2
    # Bridge between adjacent vertical bars at rows where one of the bars has a gap.
    for r,row in enumerate(grid):
        bars=[c for c,v in enumerate(row) if v==8]
        if len(bars)>=2:
            for left,right in zip(bars,bars[1:]):
                # a neighboring row's interruption joins across the intervening lane
                if all(grid[r][c]==0 for c in range(left+1,right)) and r>0 and (grid[r-1][left]==8 or grid[r-1][right]==8):
                    for c in range(left+1,right):
                        if out[r][c]==0:out[r][c]=2
    # Marker extends left/right to nearest vertical bars as a horizontal ray.
