def transform(grid):
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
    # Demonstrations show 2 traces a line alongside a series of 8 bars;
    # extend the marker line and connect the gaps in each bar.
    stripes=[r for r,row in enumerate(grid) if 8 in row]
    gaps={r:[c for c,v in enumerate(grid[r]) if v==0] for r in stripes}
    mr=next(r for r,row in enumerate(grid) if 2 in row);mc=grid[mr].index(2)
    # continue marker column to the first gap, then horizontal join to it
    c=min(gaps[stripes[0]],key=lambda x:abs(x-mc))
    for r in range(mr+1,stripes[0]):
        if out[r][mc]==0:out[r][mc]=2
    for x in range(min(mc,c),max(mc,c)+1):
        if out[mr][x]==0:out[mr][x]=2
    # Each stripe gap projects vertically, but only through adjacent clear space.
    for r in stripes:
        for c in gaps[r]:
            rr=r-1
            while rr>=0 and 8 not in grid[rr]:
                if out[rr][c]==0:out[rr][c]=2
                rr-=1
            rr=r+1
            while rr<h and 8 not in grid[rr]:
                if out[rr][c]==0:out[rr][c]=2
                rr+=1
    # Horizontal bridges span the holes on the blank row before each stripe.
    for r in stripes:
        if r>0:
            cs=gaps[r]
            lo,hi=(min(cs),max(cs)) if len(cs)>1 else (0,w-1)
            for c in range(lo,hi+1):
                if out[r-1][c]==0:out[r-1][c]=2
    # In the central band, connect the tracks across the whole grid.
    if len(stripes)>=3:
        mid=(stripes[1]+stripes[2])//2
        for c in range(w):
            if out[mid][c]==0:out[mid][c]=2
    return out
