def transform(grid):
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
    # Trace a one-cell-wide path adjacent to the broken bars, following each
    # gap to the next nearest gap in the next stripe.
    bars=[r for r,row in enumerate(grid) if 8 in row]
    gaps={r:[c for c,v in enumerate(grid[r]) if v==0] for r in bars}
    # marker at top runs vertically down to first stripe and then to its gap
    mr=next(r for r,row in enumerate(grid) if 2 in row);mc=grid[mr].index(2)
    for rr in range(mr+1,bars[0]):
        if out[rr][mc]==0:out[rr][mc]=2
    # For each bar, fill gaps and connect them to the next bar's gaps at mid-band.
    for i,r in enumerate(bars):
        cs=gaps[r]
        # at each stripe, gaps themselves become colored 2
        for c in cs:
            out[r][c]=2
        if i+1<len(bars):
            nr=bars[i+1]; ncs=gaps[nr]
            # bridge adjacent gaps across the blank band at its midpoint
            a=cs[0]; b=min(ncs,key=lambda x:abs(x-a))
            mid=(r+nr)//2
            for rr in range(r+1,mid+1):
                if out[rr][a]==0:out[rr][a]=2
            for c in range(min(a,b),max(a,b)+1):
                if out[mid][c]==0:out[mid][c]=2
            for rr in range(mid+1,nr):
                if out[rr][b]==0:out[rr][b]=2
        else:
            for c in cs:
                for rr in range(r+1,h):
                    if out[rr][c]==0:out[rr][c]=2
    return out
