def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Transform the vertical-bar examples by transposing their tracing rule.
    # For horizontal bars, put a track immediately above each bar cell, with
    # gaps redirecting the trace to a neighboring open track.
    stripes=[r for r,row in enumerate(grid) if 8 in row]
    for r in stripes:
        for c,v in enumerate(grid[r]):
            if v==8 and r>0 and grid[r-1][c]==0:
                out[r-1][c]=2
    # At any bar interruption, join the two nearest tracks laterally on that row.
    for r in stripes:
        holes=[c for c,v in enumerate(grid[r]) if v==0]
        if holes:
            # across the gap positions on the open row above
            rr=r-1
            if rr>=0:
                lo,hi=(min(holes),max(holes)) if len(holes)>1 else (holes[0]-1,holes[0]+1)
                for c in range(max(0,lo),min(w,hi+1)):
                    if out[rr][c]==0:out[rr][c]=2
    # Route marker toward nearest bar and continue along its upper edge.
    mr=next((r for r,row in enumerate(grid) if 2 in row),None)
    if mr is not None:
        mc=grid[mr].index(2)
        for c in range(mc-1,-1,-1):
            if grid[mr][c]==8:break
            out[mr][c]=2
    return out
